    <section id="budget-transactions" class="space-y-4"><div class="flex flex-wrap items-end justify-between gap-3"><h3 class="text-xl font-semibold">Recorded expenses</h3><div class="flex flex-wrap gap-2"><label><span class="sr-only">Search expenses</span><input class="input input-sm" placeholder="Search expenses" data-budget-search></label><label><span class="sr-only">Filter expenses by category</span><select class="select select-sm" data-budget-filter><option value="">All categories</option>@foreach($categories as $category)<option value="{{ $category->id }}">{{ $category->name }}</option>@endforeach</select></label></div></div><div class="overflow-x-auto rounded-sm border border-base-300 bg-base-100"><table class="table"><thead><tr><th aria-sort="descending"><span class="inline-flex items-center gap-1.5">Date <x-lucide-arrow-down class="size-3.5" aria-hidden="true" /><span class="sr-only">Newest first</span></span></th><th>Expense</th><th>Category</th><th>Amount</th>@if($canEdit)<th>Actions</th>@endif</tr></thead><tbody>@forelse($transactions as $transaction)@php $transactionCategory = $categories->firstWhere('id', $transaction->budget_category_id); @endphp<tr data-budget-expense-row data-category="{{ $transaction->budget_category_id }}"><td class="whitespace-nowrap">{{ $transaction->date->format('d M Y') }}</td><td>{{ $transaction->description ?: 'Expense' }}@if($transaction->budget_recurring_charge_id)<span class="badge badge-ghost badge-sm">Recurring payment</span>@endif @if($transaction->budget_commitment_id)<span class="badge badge-ghost badge-sm">Subscription payment</span>@endif</td><td>{{ $transactionCategory?->name ?? 'Other' }}</td><td class="whitespace-nowrap">{{ $money($transaction->amount_cents) }}</td>@if($canEdit)<td><div class="flex gap-2"><button class="btn btn-xs" type="button" data-open-dialog="budget-expense" data-edit-expense="{{ json_encode(['id' => $transaction->id, 'recurring_charge_id' => $transaction->budget_recurring_charge_id, 'category_id' => $transaction->budget_category_id, 'amount' => $amount($transaction->amount_cents), 'date' => $transaction->date->toDateString(), 'description' => $transaction->description, 'linked' => $transaction->budget_commitment_id !== null]) }}">Edit</button><form method="post" action="{{ $actionUrl('expense-remove') }}" data-budget-action data-confirm="Delete this expense? It will be removed from budget spending. You can undo this deletion." data-confirm-title="Delete expense?" data-confirm-label="Delete expense">@csrf<input type="hidden" name="version" value="{{ $period->version }}"><input type="hidden" name="id" value="{{ $transaction->id }}"><button class="btn btn-xs btn-ghost" type="submit">Delete</button></form></div></td>@endif</tr>@empty<tr><td colspan="5" class="p-8 text-center opacity-70">No expenses recorded yet.</td></tr>@endforelse</tbody></table></div><p class="hidden text-sm opacity-70" data-budget-no-results>No expenses match these filters.</p></section>
